window.LOR_VERIFY = {"cv": "304_2", "checked": "23.10.2026", "pdf": "304_2_Грибковый отит.pdf", "pages": 31, "items": {"m608": {"s": "ok", "sec": "1.4", "page": 8, "q": "H 60.8 – хронический наружный отит;", "note": "В КР подпись рубрики — «хронический наружный отит»; в МКБ-10 H60.8 — «Другие наружные отиты»."}, "m663": {"s": "ok", "sec": "1.4", "page": 8, "q": "H 66.3 – другие хронические средние отиты;"}, "m622": {"s": "ok", "sec": "1.4", "page": 8, "q": "H 62.2 – наружный отит при микозе БДУ;"}, "m378": {"s": "ok", "sec": "1.4", "page": 8, "q": "B 37.8 – поверхностный кандидоз других локализаций;"}, "m448": {"s": "ok", "sec": "1.4", "page": 8, "q": "B 44.8 – другие виды аспергиллеза (в т.ч. поверхностный аспергиллез);"}, "m49": {"s": "ok", "sec": "1.4", "page": 8, "q": "В 49 – микоз неуточненный"}, "s1": {"s": "ok", "sec": "1.1, 1.2", "page": 5, "q": "Отомикоз (ОМ) – грибковое заболевание, обусловленное развитием на коже ушной раковины, стенках наружного слухового прохода, барабанной перепонке, в барабанной полости и послеоперационной полости среднего уха различного рода плесневых и дрожжеподобных грибов [6, 18].", "note": "Возбудители и течение — разделы 1.2 и 1.5."}, "s-diag": {"s": "ok", "sec": "2.3, 2.4", "page": 14, "q": "Грибковое поражение уха может быть заподозрено на основании данных осмотра органа слуха (отоскопии), но решающее значение имеют микологические лабораторные методы исследования. При этом однократно полученные отрицательные результаты не указывают на отсутствие грибкового заболевания."}, "s-treat": {"s": "ok", "sec": "3.1", "page": 15, "q": "Всем пациентам рекомендуется начинать лечение с элиминации возбудителя. Помимо антимикотической терапии необходимо выполнять тщательный туалет наружного слухового прохода (барабанной полости, послеоперационной полости).", "note": "Системная терапия и критерий излечения — далее в разделе 3.1."}, "s-hosp": {"s": "ok", "sec": "3", "page": 15, "q": "Показаниями к госпитализации являются осложненные формы грибкового среднего отита, лабиринтит, а также при невозможности ежедневного обеспечения адекватного туалета наружного слухового прохода и/или неэффективности адекватной терапии наружного грибкового отита в амбулаторных условиях в течение 5-7 дней."}, "c-def": {"s": "ok", "sec": "1.1", "page": 6, "q": "Грибковый наружный отит – грибковое заболевание, обусловленное развитием на коже ушной раковины, стенках наружного слухового прохода, барабанной перепонке плесневых или дрожжеподобных грибов. Грибковый мирингит – развитие на барабанной перепонке плесневых грибов. Грибковый средний отит – грибковое заболевание, обусловленное развитием в барабанной полости различного рода плесневых и дрожжеподобных грибов. Микоз послеоперационной полости – грибковое заболевание, обусловленное развитием в послеоперационной полости среднего уха различного рода плесневых и дрожжеподобных грибов. Синонимы – отомикоз."}, "c-class": {"s": "ok", "sec": "1.5", "page": 8, "q": "По локализации – наружный грибковый отит, грибковый мирингит, грибковый средний отит и грибковый средний послеоперационный отит. По характеру возбудителя – плесневой, дрожжеподобный, смешанный. По клиническому течению – хронический."}, "c-etio": {"s": "ok", "sec": "1.2", "page": 6, "q": "По данным многочисленных исследований в нашей климатической зоне основными возбудителями ОМ являются плесневые грибы рода Aspergillus и дрожжеподобные грибы рода Candida. При этом аспергиллез диагностируется в 65% случаев, кандидоз в 30%. В отдельных случаях грибковое поражение уха вызывают грибы родов Penicillium, Mucor, Alterneria, Geotrichum, Kladosporium и другие, их доля составляет до 5%, соответственно. В 15% случаев присутствует сочетанное поражение грибами родов Aspergillus и Candida"}, "c-species": {"s": "ok", "sec": "1.2", "page": 6, "q": "При видовой идентификации выявляются следующие грибы: род Aspergillus – A. niger, A. fumugatus, A. orizae, A. flavus, A. ochraceus, A. versicolor, A. clavatus, A. glaucus, A. nidulans, A. terreus; род Candida – C. albicans, C. tropicalis, C. pseudotropicalis, C. krusei, C. glabrata, C. parapsillosis, C. stellatoidea, C. intermedia, C. brumpti; род Penicillium – P. notatum. P. puberulum, P. tardum, P. nidulans, P. chermesinum, P. glaucus, P. chrisogenum, P. citrinum и др."}, "c-path": {"s": "ok", "sec": "1.2", "page": 6, "q": "В основном, все виды грибов, вызывающих ОМ относятся к группе условнопатогенных и вызывают заболевание только при определенных факторах, предрасполагающих к развитию и размножению грибов, обеспечивая их переход от сапрофитии к патогенности. В связи с этим важно знать предшествующие заболеванию  условия, приводящие к реализации патогенных свойств грибов. Основными патогенетическими моментами возникновения микоза являются адгезия (прикрепление гриба к раневой поверхности, к коже и др.), колонизация гриба и его инвазивный рост. В патогенезе ОМ имеют значение различные эндогенные и экзогенные факторы. Основным экзогенным фактором при грибковом наружном отите является травма кожи в результате злоупотребления гигиеной наружного слухового прохода. Во время манипуляций в наружном слуховом проходе, проводимых пациентом самостоятельно, не только повреждается кожа наружного слухового прохода, но и удаляется ушная сера – основной фактор ее защиты [6]. Причиной адгезии и колонизации может быть повышенный уровень глюкозы у больных сахарным диабетом, т.к. на ранних стадиях этого заболевания уровень глюкозы в ушной сере повышается, что и способствует росту грибов. Эндогенными факторами, предрасполагающими к возникновению ОМ, являются соматические заболевания. Сопутствующие им общее ослабление организма, нарушение обмена веществ, гиповитаминозы могут играть немаловажную роль в возникновении ОМ. Другим немаловажным патогенетическим фактором в развитии ОМ является проводимая больным длительная общая и местная антибиотикотерапия, применение кортикостероидов. Подавляя рост патогенной и нормальной бактериальной флоры, антибиотики ( J01 Антибактериальные препараты системного действия ) тем самым способствуют развитию дисбиоза и активизации грибов. Применение кортикостероидов системного действия в больших дозировках, приводит к снижению неспецифического и специфического иммунитета. Кроме того, к возникновению грибковых осложнений могут привести лечение иммунодепрессантами и лучевая терапия"}, "c-path-po": {"s": "ok", "sec": "1.2", "page": 7, "q": "В патогенезе микотического заболевания послеоперационной полости уха в качестве причинного фактора в первую очередь следует назвать длительный воспалительный процесс в послеоперационной полости, сопровождающийся повреждением эпителия. При этом воспалительный экссудат, содержащий углеводы, белки, пептоны, минеральные соли и другие вещества, является хорошей питательной средой, а постоянная температура, влажность, свободный доступ воздуха в послеоперационную полость среднего уха представляют оптимальные условия для активизации и развития грибов. Пусковым механизмом возникновения микоза послеоперационной полости среднего уха могут явиться травма уха, в том числе и операционная, а также попадание нестерильной воды. Определенную роль здесь также играют неблагоприятные условия внешней среды: влажность, запыленность, производственный контакт с антибиотиками"}, "c-recur": {"s": "ok", "sec": "1.2", "page": 8, "q": "Для грибкового отита характерно рецидивирующее течение."}, "c-compl": {"s": "ok", "sec": "2.1", "page": 10, "q": "Основные жалобы при микотическом наружном отите – жидкие выделения (при кандидозе), образование корочек, пробок в наружном слуховом проходе (при аспергиллезе), зуд, боль, заложенность уха. Некоторые больные в острой стадии могут предъявлять жалобы на головную боль, повышение температуры тела, повышенную чувствительность ушной раковины, заушной области и наружного слухового прохода. При всех формах микотического наружного отита нарушение слуха или не выявляется, или оно незначительное по типу поражения звукопроводящего аппарата.  Клинические проявления при микотическом среднем отите и микозе послеоперационной полости среднего уха характеризуются как симптоматикой воспалительного гнойного процесса среднего уха, так и самим микозом. Основными жалобами больных с микотическим средним отитом являются: понижение слуха, наличие выделений из уха, периодически возникающий зуд в ухе, могут быть головокружения [13, 14]. Течение ОМ длительное с периодическими обострениями. Обострения характеризуются выраженной ушной болью, зудом, заложенностью уха, выделениями из него, головной болью, головокружением [13, 15]."}, "c-anam": {"s": "ok", "sec": "2.1", "page": 10, "q": "При опросе необходимо уточнить время начала заболевания и особенности течения. Следует выяснить, не было ли ранее отита, микоза другой локализации, каковы периодичность, длительность и характер обострений. Учитывается ранее проводимое лечение (местное или общее), его эффективность: не было ли ухудшения состояния, рецидивов. Обязательно надо выяснить, лечились ли ранее больные антибиотиками, кортикостероидами, иммунодепрессантами (длительность и интенсивность лечения), особенности производственных и бытовых условий, перенесенные ранее заболевания, аллергологический анамнез. У больных ОМ отмечается увеличение частоты обострений, отсутствие или незначительный эффект от стандартных методов лечения."}, "c-cand": {"s": "ok", "sec": "1.6", "page": 9, "q": "При микозе вызванном дрожжеподобными грибами в воспалительный процесс может включаться кожа ушных раковин и околоушная область. Для кандидозного поражения наружного уха характерно: гиперемия, инфильтрация и мацерация кожи наружного слухового прохода, гиперемия барабанной перепонки при наружном отите, утолщение слизистой оболочки, наличие густого мутного отделяемого в просвете барабанной полости. Нарушение эпителизации послеоперационной полости. Выделения на стенках слухового прохода менее густые, в отличие от воспаления вызванного плесневыми грибами. Цвет отделяемого имеет беловатый оттенок. При распространении воспаления на ушную раковину определяется гиперемия кожи с эрозиями, возможны грануляции и чешуйки, налеты на коже ушной раковины беловатые, легко снимающиеся. Вовлечение в воспалительный процесс ушной раковины может стать причиной возникновения хондроперихондрита с последующей деформацией ушной раковины"}, "c-asp": {"s": "ok", "sec": "1.6", "page": 9, "q": "При отите, вызванном плесневыми грибами рода Aspergillus, клиническая картина носит специфический характер. В просвете наружного слухового прохода определяются казеозно-некротические массы, инфильтрация кожи наружного слухового прохода более выражена в костном отделе, возможны явлениями мирингита. Наложения на стенках наружного слухового прохода беловато-серые с черными вкраплениями напоминающие «молотый перец» или «промокшую газету». При поражении наружного слухового прохода грибами Aspergillus glaucus, патологическое оделяемое имеет специфический зеленоватый оттенок."}, "c-pen": {"s": "ok", "sec": "1.6", "page": 9, "q": "При поражении наружного уха плесневыми грибами рода Penicillium, клинические проявления также специфичны. Цвет отделяемого имеет желтоватый оттенок, в ряде случаев напоминает ушную серу. Кожа наружного слухового прохода инфильтрирована, патологическое отделяемое определяется на всем протяжении наружного слухового прохода. Дополнительными элементами на коже наружного слухового прохода могут быть сухие корочки и пленки"}, "c-geo": {"s": "ok", "sec": "1.6", "page": 9, "q": "Для геотрихозного воспаления наружного слухового прохода вызванного штаммом (Geotrichum capitatum), характерными клиническими проявлениями являются: выраженная инфильтрация кожи наружного слухового прохода, явления мирингита. В просвете наружного слухового прохода определяются плотные «замазкообразные» серовато-желтые грибковые массы. Патологическое отделяемое определяется на всем протяжении наружного слухового прохода."}, "d-base": {"s": "ok", "sec": "2", "page": 10, "q": "Критерии установления диагноза основаны на анализе результатов комплексного обследования пациента:  жалоб;  анамнестических данных;  физикального обследования;  лабораторных исследований;  инструментального обследования."}, "d-oto": {"s": "ok", "sec": "2.4", "page": 14, "q": "Всем пациентам рекомендуется проведение осмотра наружного слухового прохода, барабанной перепонки, барабанной полости и послеоперационной полости среднего уха с использованием микроскопа или отоскопа [3, 13, 21]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарии: Осмотр органа слуха может быть осуществлен с помощью микроскопов и бинокулярных луп, торцевых ригидных эндоскопов (отоскопов)[3, 6, 21]. При всех формах ОМ отмечен общий микроотоскопический признак – наличие у всех больных окрашенного отделяемого в просвете наружного слухового прохода и/или среднего уха. Диагноз «Отомикоз», тем не менее, может быть поставлен только после верификации возбудителя"}, "d-oto-optics": {"s": "ok", "sec": "2.2", "page": 11, "q": "Осмотр органа слуха (Отоскопию) рекомендуется проводить с использованием увеличивающей оптической техники (отоскоп, микроскоп, торцевой эндоскоп)"}, "d-oto-cand": {"s": "ok", "sec": "2.2", "page": 11, "q": "При кандидозном поражении наружного слухового прохода отмечается умеренное сужение просвета наружного слухового прохода, более выраженное в хрящевом отделе, барабанная перепонка гиперемирована. Патологическое отделяемое более жидкой консистенции, чем при плесневом микозе, чаще беловатого цвета и творожистой консистенции. Процесс часто распространяется на кожу ушной раковины [5, 11, 12]."}, "d-oto-asp": {"s": "ok", "sec": "2.2", "page": 11, "q": "При аспергиллезном поражении наружный слуховой проход также может быть сужен за счет инфильтрации стенок, однако, в отличие от пенициллиоза, инфильтрация кожи более выражена в костном отделе. Почти во всех случаях в процесс вовлекается барабанная перепонка, отмечается ее инфильтрация, утолщение, исчезновение опознавательных контуров. В ряде случаев наблюдаются грануляции. Патологическое отделяемое при аспергиллезном поражении более обильное, чем при пенициллиозном и отличается по цвету. В большинстве случаев оно различных оттенков серого цвета, иногда с черными точками, может быть холестеатомо- или сероподобным, напоминает промокшую газету."}, "d-oto-pen": {"s": "ok", "sec": "2.2", "page": 11, "q": "При пенициллиозе процесс локализуется в хрящевом отделе наружного слухового прохода. Отмечается умеренная инфильтрация кожи наружного слухового прохода, не приводящая к полному закрытию слухового прохода. Барабанная перепонка в большинстве случаев гиперемирована, иногда поверхность барабанной перепонки  эрозирована, может быть выпячивание, что создает ложное впечатление о наличии перфорации. Характерным и специфическим для пенициллиозного поражения наружного уха является вид патологического отделяемого, имеющего различные оттенки желтого цвета, и в ряде случаев напоминает ушную серу. Патологическое отделяемое расположено на всем протяжении наружного слухового прохода и может сочетаться с сухими корочками и пленками."}, "d-oto-mid": {"s": "ok", "sec": "2.2", "page": 12, "q": "Объективным признаком микотического поражения среднего уха является наличие специфического отделяемого, цвет и консистенция которого зависят от вида гриба возбудителя. Нередко присоединяются явления наружного отита. Барабанная перепонка гиперемирована, инфильтрирована с наличием перфораций различных размеров. Во всех случаях обозримая слизистая оболочка барабанной полости гиперемирована, инфильтрирована, иногда образуются грануляции"}, "d-oto-postop": {"s": "ok", "sec": "2.2", "page": 12, "q": "При микозе послеоперационной полости среднего уха в последней отсутствует или резко замедлена эпителизация, стенки наружного слухового прохода гиперемированы, неравномерно инфильтрированы, неотимпанальная полость бывает заполнена патологическим отделяемым аналогичного вида, что и при ОМ другой локализации, встречаются мелкие кровоточащие грануляции"}, "d-myc": {"s": "ok", "sec": "2.3", "page": 13, "q": "Всем пациентам рекомендуется проведение микологического исследования: o Микроскопическое исследование отделяемого из ушей на грибы (дрожжевые и мицелиальные). o Микробиологическое (культуральное) исследование отделяемого из ушей на дрожжевые грибы. o Микробиологическое (культуральное) исследование отделяемого из ушей на мицелиальные грибы [2, 3, 4, 5, 6, 11, 13, 23, 34]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарии: проводить указанные выше микологические исследования у пациентов с хроническим отитом в следующих случаях: o у пациентов с частыми обострениями (1 раз в 2 месяца); o при неэффективности противовоспалительной антибактериальной терапии хронического отита; o при выявлении характерной отоскопической картины микоза. После установки диагноза: «ОМ» и проведения соответствующей терапии, показаны повторные контрольные микологические исследования."}, "d-myc-how": {"s": "ok", "sec": "2.3", "page": 13, "q": "Для отбора образцов биологического материала на микологическое исследование используют аттиковый зонд или ложку Фолькмана. Патологическое отделяемое желательно отбирать из глубоких отделов наружного слухового прохода под контролем микроскопа или отоскопа или торцевого эндоскопа. Патологический материал помещается между двумя обезжиренными стерильными предметными стеклами и микроскопируется под увеличением х100, х200, х400 [2, 3, 4, 5, 7, 16, 23, 35]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4) Комментарии: Микроскопическое исследование (A26.01.015 Микроскопическое исследование соскоба с кожи на грибы (дрожжевые, плесневые, дерматомицеты)) является наиболее информативным методом, надежно идентифицирующим возбудителя заболевания [2, 3, 23, 24].  Основным критерием постановки диагноза микоза при посеве патологического отделяемого на питательные среды является титр выявленных грибов при посеве не менее 104 КОЕ/мл.", "note": "«104 КОЕ/мл» в тексте PDF — 10⁴ КОЕ/мл (верхний индекс потерян при извлечении)."}, "d-myc-rep": {"s": "ok", "sec": "2.3", "page": 14, "q": "Рекомендуется проведение повторного исследования патологического отделяемого [2, 6, 7, 13, 23]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарии: Грибковое поражение уха может быть заподозрено на основании данных осмотра органа слуха (отоскопии), но решающее значение имеют микологические лабораторные методы исследования. При этом однократно полученные отрицательные результаты не указывают на отсутствие грибкового заболевания. В данной ситуации рекомендовано проведение повторного исследования патологического отделяемого. И наоборот, единичный рост грибов в посеве не всегда свидетельствует о грибковом патологическом процессе."}, "d-lab": {"s": "ok", "sec": "2.3", "page": 12, "q": "У пациентов с затяжным и рецидивирующем течением от омикозас целью выявления сопутствующей патологии рекомендуется проведение общеклинических исследований[3, 6, 13]: o Общий (Клинический) анализ крови; o Анализ крови биохимический общетерапевтический: исследование уровня глюкозы в крови, исследование уровня общего белка в крови; определение активности аспартатаминотрансферазы в крови, определение активности аланинаминотрансферазы в крови, исследование уровня креатинина в крови; o Определение антител классов М, G (IgM, IgG) к вирусу иммунодефицита человека ВИЧ-1 (Human immunodeficiency virus HIV 1) в крови, o Определение антител классов М, G (IgM, IgG) к вирусу иммунодефицита человека ВИЧ-2 (Human immunodeficiency virus HIV 2) в крови; o Определение антител к бледной трепонеме (Treponema pallidum) в крови; o Определение антигена (HbsAg) вируса гепатита В (Hepatitis В virus) в крови; o Определение антигена вируса гепатита С (Hepatitis С virus) в крови.  Уровень убедительности рекомендаций В (уровень достоверности доказательств – 3) Комментарии: общеклинические исследования выполняются для исключения сопутствующей патологии и выявления фоновых заболеваний."}, "d-consult": {"s": "ok", "sec": "2.5", "page": 14, "q": "Рекомендовано при поражении уха на фоне системных, в том числе инфекционных заболеваний, консультация соответствующего врача-специалиста и дополнительное обследование"}, "t-elim": {"s": "ok", "sec": "3.1", "page": 15, "q": "Всем пациентам рекомендуется начинать лечение с элиминации возбудителя. Помимо антимикотической терапии необходимо выполнять тщательный туалет наружного слухового прохода (барабанной полости, послеоперационной полости). [1, 5, 6, 8, 11, 12] Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: При проведении лечения необходимо учитывать предшествующие эпизоды грибкового поражения и лечения противогрибковыми препаратами для местного применения(D01A)."}, "t-start": {"s": "ok", "sec": "3.1", "page": 15, "q": "Всем пациентам рекомендуется начинать терапию отита до получения результатов назначая разные группы препаратов для местного применения."}, "tb-ext": {"s": "ok", "sec": "3.1", "page": 17, "q": "Локализация поражения Наружное ухо Среднее ухо Послеоперационная полость Способ применения Местно Местно Внутрь Местно Внутрь Виды грибов Дрожжеподобные Плесневые Нафтифин 1% раствор + Нафтифин 1% раствор + клотримазол 1% раствор хлорнитрофенол 1% раствор", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 17.", "img": [17]}, "tb-mid": {"s": "ok", "sec": "3.1", "page": 17, "q": "Таблица 1 - Схема лечения отомикоза противогрибковыми препаратами для местного применения в виде аппликаций и противогрибковыми препаратами системного действия [13, 21, 25, 26, 27, 30, 31]. Локализация поражения Наружное ухо Среднее ухо", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 17.", "img": [17]}, "tb-mid-po": {"s": "ok", "sec": "3.1", "page": 17, "q": "#Флуконазол**, капсулы #Итраконазол, капсулы", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 17.", "img": [17]}, "tb-po": {"s": "ok", "sec": "3.1", "page": 17, "q": "Таблица 1 - Схема лечения отомикоза противогрибковыми препаратами для местного применения в виде аппликаций и противогрибковыми препаратами системного действия [13, 21, 25, 26, 27, 30, 31]. Локализация поражения Наружное ухо Среднее ухо Послеоперационная полость", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 17.", "img": [17]}, "tb-po-po": {"s": "ok", "sec": "3.1", "page": 17, "q": "Итраконазол, капсулы или Флуконазол**, капсулы #тербинафин, таблетки (с 3", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 17.", "img": [17]}, "t-cand": {"s": "ok", "sec": "3.1", "page": 15, "q": "При кандидозном наружном отите показана комбинация 1% раствора #клотримазола и 1% раствора #нафтифина в виде аппликаций, продолжительностью 5-10 мин каждая 2 раза в сутки в течение 14 дней, с продолжением терапии в течение 14 дней после стихания клинических признаков и/или до получения 3-кратного отрицательного лабораторного анализа (Табл. 1). При кандидомикозе возможно также применение миконазола, натамицина** или #эконазола"}, "t-mold": {"s": "ok", "sec": "3.1", "page": 15, "q": "При наружном отите, вызванном плесневыми грибами, препаратами выбора для проведения местного лечения являются #хлорнитрофенол и 1% раствор #нафтифина,  применяемые также в виде аппликаций на кожу наружного слухового прохода 2 раза в день продолжительностью по 5-10 мин каждая в течение 10-14 дней. Необходимо также продолжать лечение в течение 14 дней после стихания клинических признаков и/или до получения 3-кратного отрицательного лабораторного анализа [7, 4]."}, "t-mix": {"s": "ok", "sec": "3.1", "page": 16, "q": "При отите, вызванным грибково-бактериальной ассоциацией препаратом выбора является комбинированный препарат - Укажите, пожалуйста, в соответствии с АТХклассификацией: S02C Кортикостероиды в комбинации с противомикробными средствами #(хлорамфеникол+беклометазон+клотримазол+лидокиан) в виде закапывания в наружный слуховой проход по 4-5 капель * 3-4 р/*день в течение 10 дней (детям с 6 лет).", "note": "В тексте КР здесь осталась служебная пометка редактора «Укажите, пожалуйста, в соответствии с АТХ классификацией»."}, "t-sys-cand": {"s": "ok", "sec": "3.1", "page": 16, "q": "При лечении грибкового среднего отита и микоза послеоперационной полости среднего уха, вызванных грибами рода Candida рекомендуется не только лечение препаратами для местного применения, но и проведение терапии противогрибковым препаратом системного действия – #флуконазол** в возрастной дозировке"}, "t-sys-mold": {"s": "ok", "sec": "3.1", "page": 16, "q": "При лечении грибкового среднего отита и микоза послеоперационной полости среднего уха, вызванного плесневыми грибами, рекомендуется назначение противогрибковых препаратов системного действия – итраконазол или тербинафин [17]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарии: Местная терапия схожа с таковой при лечении наружного грибкового отита"}, "t-sys-dose": {"s": "ok", "sec": "3.1", "page": 17, "q": "Таблица 2 – Дозы и режимы применения противогрибковых препаратов системного действия при отомикозе [13, 21, 25, 26, 27, 30, 31].  Препараты Дозы и режимы применения #Флуконазол** Внутрь, 50–100 мг 1 раз в сутки в течение 14 дней #Итраконазол Внутрь, 200 мг 1 раз в сутки в течение 10–14 дней #Тербинафин Внутрь, 250 мг в сутки в течение 16 дней"}, "t-eff": {"s": "ok", "sec": "3.1", "page": 16, "q": "Критерием эффективности лечения у всех пациентов рекомендуется считать полное клиническое излечение в течение месяца, подтвержденное как клинической картиной, так и отрицательными результатами микологического исследования"}, "t-drugs": {"s": "ok", "sec": "3.1", "page": 16, "q": "Препарат #нафтифин (АТХ: D01AE22) Другие противогрибковые препараты для местного применения. Действие препарата основывается на подавление активности фермента эпоксидазы сквалена, ответственного за одну из стадий биосинтеза эргостерина. Из-за нехватки эргостерина происходит нарушение формирования клеточной мембраны гриба, что проявляется как фунгистатический эффект препарата. Данный препарат обладает активностью в отношении дрожжеподобных грибов рода Candida. Кроме того, по отношению к плесневым грибам данный препарат обладает и фунгицидным эффектом. К  достоинству препарата относятся противовоспалительный эффект и длительно сохраняющиеся эффективные концентрации на коже [4, 27, 29, 31]. Препарат #Хлорнитрофенол – (АТХ: D.01.A.E) Другие противогрибковые препараты для местного применения: оказывает противогрибковое, антибактериальное действие. Подавляет рост Microsporum canis, Trichophyton gypseum (в концентрации 0,0001 %), Candida albicans (в концентрации 0,0007 %). 0,003 % раствор оказывает фунгицидное действие. В высоких концентрациях проявляет активность в отношении грамположительных и грамотрицательных бактерий (включая Proteus vulgaris и Pseudomonas aeruginosa). Применение вещества #Хлорнитрофенол - грибковые заболевания кожи, в т.ч. эпидермофития, трихофития, кандидоз, грибковая экзема; микоз наружного слухового прохода [32]. Препарат #клотримазол – противогрибковый препарат производное имидазоола и триазола.. #Клотримазол является высокоспецифичным препаратом к широкому спектру дрожжеподобных патогенов рода Candida. Данный препарат препятствует синтезу эргостерина за счет действия на фермент 14α-деметилазу ланостерина вызывая лизис клетки гриба. Эффект препарата преимущественно фунгистатический"}, "t-toilet": {"s": "ok", "sec": "3.3", "page": 18, "q": "Всем больным рекомендуется кроме проведения местной терапии осуществлять предварительную тщательную очистку уха от патологического отделяемого [3, 6, 8, 9, 13, 25, 29, 30]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4) Комментарии: Туалет уха производится только врачом при помощи аттикового зонда и/или ушного зонда с навивкой и намотанной на него ватой, смоченной противогрибковыми препаратами для местного применения или вакуум-экстрактора. Тщательному туалету уха придается особое значение, поскольку даже незначительное количество микотических масс заметно удлиняет длительность лечения и, соответственно, растягивает сроки выздоровления. При наружном микотическом отите большое значение придается очистке передненижнего отдела наружного слухового прохода. При среднем микотическом отите полностью удаляются микотические массы из области перфораций барабанной перепонки. При больших перфорациях, с целью удаления микотических масс, производится промывание барабанной полости антисептики и дезинфицирующими средствами, в частности, 0,01% раствором бензилдиметила [3(миристоиламино)пропил] аммония хлорида моногидрата. Аналогично поступают при лечении микоза послеоперационной полости среднего уха. До начала лечения при наличии полипов, грануляций производится их удаление или туширование 10% раствором  нитрата серебра. При послеоперационном микозе – тщательно очищается вся неотимпанальная полость, особенно в заднем отделе, за шпорой."}, "t-turunda": {"s": "ok", "sec": "7", "page": 20, "q": "Всем пациентам рекомендовано введение препарата в ухо на турунде. Комментарии: Закапывание спиртсодержащего лекарственного препарата в наружный слуховой проход может привести к более длительному нахождению лекарственного средства в наружном слуховом проходе и вызвать его раздражение, а при попадании на слизистую оболочку барабанной полости при среднем отите – резкую боль и усиление отека слизистой оболочки, усугубление мукозита, появление грануляций. Группа экспертов рекомендует введение в наружный слуховой проход турунды, пропитанной раствором лекарственного препарата, что позволяет увеличить время лекарственного действия препарата"}, "t-surg": {"s": "ok", "sec": "3.2", "page": 18, "q": "Рекомендуется до начала медикаментозной терапии при наличии полипов, грануляций производить их удаление или туширование 10% раствором нитрата серебра (Код АТХ D08AL01 Серебра нитрат AgNO3) [3, 6, 9, 33]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: После туширования обязательна обработка противогрибковыми препаратами для местного применения, например, нафтифином или хлорнитрофенолом."}, "t-nophysio": {"s": "ok", "sec": "3.3", "page": 19, "q": "Всем пациентам не рекомендуется физиотерапевтическое воздействие [3]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: Необходимо ограничить воздействие вредных факторов внешней среды: контакт с пылью, газами, нахождение в помещениях с повышенной влажность. Решающее значение имеет предотвращение попадания воды в ухо."}, "h-hosp": {"s": "ok", "sec": "3", "page": 15, "q": "Показаниями к госпитализации являются осложненные формы грибкового среднего отита, лабиринтит, а также при невозможности ежедневного обеспечения адекватного туалета наружного слухового прохода и/или неэффективности адекватной терапии наружного грибкового отита в амбулаторных условиях в течение 5-7 дней."}, "h-org": {"s": "ok", "sec": "4, 6", "page": 20, "q": "Первичная медико-санитарная помощь пациентам, нуждающимся в лечении, реабилитации и оздоровительных мероприятиях оказывается врачами общей практики (семейного врача) и врачами-оториноларингологами первичного звена.", "note": "Реабилитация: раздел 4 «Не проводится»."}, "p-disp": {"s": "ok", "sec": "5", "page": 19, "q": "Рекомендуется всем пациентам с грибковым отитом проводить диспансерный прием врачом-оториноларингологом 1 раз в 3 месяца, а при благоприятном течении 1 раз в полгода в течение 2 лет [3]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: Основные меры по профилактике ОМ должны быть направлены на устранение факторов, имеющих значение в патогенезе грибкового заболевания: правильный туалет наружного слухового прохода и ушной раковины; коррекция гликемического профиля; общеукрепляющая терапия."}, "p-recur": {"s": "ok", "sec": "5", "page": 19, "q": "Профилактика рецидивов ОМ: 1. динамическое наблюдение за больным в течение 6 месяцев; 2. проведение курса профилактического лечения; 3. один раз в неделю (в течение 4-6 недель) смазывание кожи наружного слухового прохода нафтифином или хлорнитрофенолом."}, "p-reseed": {"s": "ok", "sec": "7", "page": 20, "q": "Рекомендуется делать повторные посевы из уха до получения микробиологического подтверждения элиминации возбудителя."}}, "terms": {"a:БДУ": {"t": "БДУ", "q": "без дальнейших уточнений", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])БДУ(?![\\w-])"}, "a:ОМ": {"t": "ОМ", "q": "отомикоз", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ОМ(?![\\w-])"}, "d:Отомикоз": {"t": "Отомикоз (ОМ)", "q": "грибковое заболевание, обусловленное развитием на коже ушной раковины, стенках наружного слухового прохода, барабанной перепонке, в барабанной полости и послеоперационной полости среднего уха различного рода плесневых и дрожжеподобных грибов [6, 18].", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?:[оО]томикоз)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])"}, "d:Наружный отит": {"t": "Наружный отит (НО)", "q": "воспаление ушной раковины, наружного слухового прохода и эпидермального слоя барабанной перепонки.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?:[нН]аружн|[нН]аруж[оеё]н)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?\\s+(?:отит)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "21_3", "kr": "Наружный отит у детей", "slug": "naruzhnyi-otit-u-detei"}, "d:Отомикроскопия": {"t": "Отомикроскопия", "q": "осмотр наружного слухового прохода и барабанной перепонки под микроскопом. Используется для детального осмотра барабанной перепонки, а при наличии перфорации – структур барабанной полости.", "sec": "Термины и определения", "page": 4, "re": "(?<![\\w-])(?:[оО]томикроскоп)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "315_4", "kr": "Отосклероз", "slug": "otoskleroz"}, "d:Мукозит": {"t": "Мукозит", "q": "хроническое катаральное воспаление слизистой оболочки среднего уха.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?:[мМ]укозит)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "698_2", "kr": "Хронический средний отит", "slug": "hronicheskii-srednii-otit"}, "d:МКБ-10": {"t": "МКБ-10", "q": "международная классификация болезней, десятый пересмотр.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])МКБ\\-(?:10)(?![\\w-])", "cv": "1068_1", "kr": "Врожденный множественный артрогрипоз", "slug": "cr:1068_1"}, "d:Гликемия": {"t": "Гликемия", "q": "концентрация глюкозы в крови.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[гГ]лик[её]м)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "286_3", "kr": "Сахарный диабет 1 типа у взрослых", "slug": "cr:286_3"}, "d:Гепатит": {"t": "Гепатит", "q": "воспаление в ткани печени, характеризуется наличием некровоспалительных изменений в биоптате печени.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[гГ][её]патит)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "516_3", "kr": "Хронический вирусный гепатит С ", "slug": "cr:516_3"}, "d:Лучевая терапия": {"t": "Лучевая терапия", "q": "метод локального лучевого воздействия на опухоль/ткани/органы", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[лЛ]уч[её]в)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?\\s+(?:т[её]рап)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "67_2", "kr": "Злокачественные новообразования почек, почечных лоханок, мочеточника, других и неуточненных мочевых органов", "slug": "cr:67_2"}, "d:Хронический гнойный средний отит": {"t": "Хронический гнойный средний отит (ХГСО)", "q": "хроническое воспаление полостей среднего уха, характеризующееся наличием стойкой перфорации барабанной перепонки, постоянным или периодически возникающим гноетечением из уха и прогрессирующим снижением слуха более 3 месяцев", "sec": "1.1", "page": null, "re": "(?<![\\w-])(?:[хХ]ронич[её]ск|[хХ]ронич[её]с[оеё]к)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?\\s+(?:гнойн|гной[оеё]н)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?\\s+(?:ср[её]дн|ср[её]д[оеё]н)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?\\s+(?:отит)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "698_2", "kr": "Хронический средний отит", "slug": "cr:698_2"}, "d:Полип": {"t": "Полип", "q": "собирательный термин, используемый для обозначения различных по происхождению патологических разрастаний тканей над слизистой оболочкой.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[пП]олип)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "738_2", "kr": "Аденоматозный полипозный синдром", "slug": "cr:738_2"}, "d:Антигены": {"t": "Антигены", "q": "чужеродные вещества, стимулирующие выработку антител иммунной системой. Антигены могут быть живыми (например, вирусы или бактерии) или инактивированными.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[аА]нтиг[её]н)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "79_2", "kr": "ВИЧ-инфекция у взрослых", "slug": "cr:79_2"}, "d:Антитела": {"t": "Антитела", "q": "белки, вырабатываемые иммунной системой в ответ на воздействие специфических антигенов и помогающие организму бороться с инфекциями и обезвреживать чужеродные вещества.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[аА]нтит[её]л)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "79_2", "kr": "ВИЧ-инфекция у взрослых", "slug": "cr:79_2"}, "d:Кандидоз": {"t": "Кандидоз", "q": "грибковое заболевание, вызываемое дрожжеподобными грибами рода Candida .", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?:[кК]андидоз)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "cv": "944_1", "kr": "Кандидоз новорождённых", "slug": "cr:944_1"}, "d:Отоскопия": {"t": "Отоскопия", "q": "Осмотр наружного слухового прохода и барабанной перепонки через ушную воронку, отоскоп, эндоскоп или микроскоп. Пневматическая воронка Зигле даёт увеличение и, сгущая и разрежая воздух в слуховом проходе, позволяет оценить подвижность барабанной перепонки.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 13", "re": "(?<![\\w-])(?:[оО]тоскоп)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "pages": null}, "d:Ушная сера": {"t": "Ушная сера", "q": "Смесь секрета поверхностно расположенных сальных желёз, а также серных и апокриновых желёз, лежащих глубже в коже наружного слухового прохода. Служит естественной смазкой стенок прохода.", "book": "Нацруководство «Оториноларингология» под ред. В. Т. Пальчуна, гл. 11 «Болезни уха», раздел «Серная пробка»; Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 317", "re": "(?<![\\w-])(?:(?i:ушн\\w+\\s+сер\\w+))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "663_2"]}, "d:Лабиринтит": {"t": "Лабиринтит", "q": "Воспалительное заболевание внутреннего уха, возникающее при проникновении в него патогенных микроорганизмов или их токсинов и проявляющееся сочетанным нарушением функций периферических рецепторов вестибулярного и слухового анализаторов.", "book": "Нацруководство «Оториноларингология» под ред. В. Т. Пальчуна, гл. 11 «Болезни уха», раздел «Лабиринтит»", "re": "(?<![\\w-])(?:[лЛ]абиринтит)(?:ьями|ами|ями|ого|его|ому|ему|ыми|ими|ьев|ьям|ьях|ом|ем|ём|ой|ей|ою|ею|ью|ам|ям|ах|ях|ов|ев|ий|ия|ии|ию|ие|ый|ая|ое|ые|ым|им|ых|их|ую|юю|ья|ьи|а|я|ы|и|у|ю|е|о|ь)?(?![\\w-])", "pages": ["18_2", "22_3", "304_2", "315_4", "518_3", "609_2", "698_2", "812_1"]}, "d:Опознавательные знаки барабанной перепонки": {"t": "Опознавательные знаки барабанной перепонки", "q": "Ориентиры на поверхности барабанной перепонки: выступающий короткий отросток молоточка с отходящими от него передней и задней складками, рукоятка молоточка, пупок (умбо) и световой конус.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 66–67", "re": "(?<![\\w-])(?:(?i:опознавательн\\w+\\s+(знак\\w*|контур\\w*)))\\w*(?![\\w-])", "pages": ["22_3", "304_2", "314_3", "315_4", "518_3"]}, "d:Аттиковый зонд": {"t": "Аттиковый зонд", "q": "Зонд с загнутым концом (зонд Воячека) для осторожного зондирования краевой перфорации, особенно в ненатянутой части барабанной перепонки. Шероховатость костной стенки указывает на кариес; кончиком зонда можно извлечь холестеатомные массы или гной из аттика.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 69", "re": "(?<![\\w-])(?:(?i:аттиков\\w+\\s+зонд\\w*))\\w*(?![\\w-])", "pages": ["21_3", "304_2"]}, "d:Мирингит": {"t": "Мирингит", "q": "Воспаление барабанной перепонки. Буллёзный мирингит обычно возникает при гриппозной инфекции: влажное синюшно-багровое воспаление с пузырями; геморрагические пузырьки через несколько дней высыхают и заживают без осложнений, боль крайне сильная.", "book": "Behrbohm H., Kaschke O., Nawka T. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), с. 165 (PDF)", "re": "(?<![\\w-])(?:(?i:мирингит\\w*))\\w*(?![\\w-])", "pages": ["21_3", "304_2"]}, "d:Ушная раковина": {"t": "Ушная раковина", "q": "Основу ушной раковины составляет эластический хрящ, покрытый надхрящницей. Кожа наружной поверхности плотно спаяна с надхрящницей и неподвижна относительно неё, на внутренней поверхности раковины кожа подвижна.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 268", "re": "(?<![\\w-])(?:(?i:у)шн\\w+\\s+раковин\\w+)\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "663_2", "812_1"]}, "d:Барабанная перепонка": {"t": "Барабанная перепонка", "q": "Тонкая округлая и довольно прочная пластинка, которая отделяет наружный слуховой проход от барабанной полости, то есть наружное ухо от среднего. На три четверти окружности она закреплена в барабанной борозде височной кости.", "book": "Гайворонский И. В. и соавт. «Функциональная анатомия ЛОР-органов» (СПб.: СпецЛит, 2022), с. 57 PDF", "re": "(?<![\\w-])(?:(?i:барабанн\\w+\\s+перепонк\\w+))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "314_3", "663_2", "812_1"]}, "d:Барабанная полость": {"t": "Барабанная полость", "q": "Пространство между наружным слуховым проходом и лабиринтом. В ней расположены цепочка слуховых косточек (молоточек, наковальня, стремя) со связками, внутриушные мышцы, сосуды и нервы; стенки покрыты слизистой оболочкой.", "book": "Гайворонский И. В. и соавт. «Функциональная анатомия ЛОР-органов» (СПб.: СпецЛит, 2022), с. 61 PDF", "re": "(?<![\\w-])(?:(?i:барабанн\\w+\\s+полост\\w+))\\w*(?![\\w-])", "pages": ["304_2", "311_2", "314_3", "812_1"]}, "d:Грануляции": {"t": "Грануляции", "q": "Грануляционная ткань: хорошо васкуляризированная ткань, содержащая коллаген и протеогликаны. При заживлении она постепенно формируется и замещает сгусток на месте повреждения.", "book": "Watkinson J., Clarke R. (eds.) «Scott-Brown's Otorhinolaryngology and Head and Neck Surgery», т. 1, с. 145, 150 (PDF)", "re": "(?<![\\w-])(?:(?i:грануляци\\w+))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "663_2"]}, "d:Туалет уха": {"t": "Туалет уха", "q": "Тщательная очистка уха от патологического отделяемого, которую выполняет врач аттиковым зондом и тампоном (при микозе — смоченным противогрибковым препаратом). Остатки отделяемого заметно удлиняют сроки лечения.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 322", "re": "(?<![\\w-])(?:(?i:туалет\\w*\\s+(?:уха|(?:наружного\\s+)?слухового\\s+прохода|НСП)))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "663_2"]}, "d:Aspergillus": {"t": "Aspergillus", "q": "Род плесневых грибов, включающий более 185 видов, из которых около 20 вызывают инфекции у человека. Грибы повсеместно распространены, часто выделяются из почвы и растительных остатков; поражают, в частности, околоносовые пазухи и наружный слуховой проход (отомикоз).", "book": "Watkinson J., Clarke R. (eds.) «Scott-Brown's Otorhinolaryngology and Head and Neck Surgery», т. 1, с. 253–254 (PDF)", "re": "(?<![\\w-])(?:Aspergillus)\\w*(?![\\w-])", "pages": ["21_3", "304_2"]}, "d:Candida": {"t": "Candida", "q": "Род дрожжевых грибов, наиболее частая причина оппортунистических микозов. Грибы часто колонизируют кожу и слизистые оболочки; наиболее патогенный и самый частый вид — Candida albicans. Инфекции, которые они вызывают, называют кандидозом; в оториноларингологии чаще всего поражаются ротоглотка, гортань и наружный слуховой проход.", "book": "Watkinson J., Clarke R. (eds.) «Scott-Brown's Otorhinolaryngology and Head and Neck Surgery», т. 1, с. 254 (PDF)", "re": "(?<![\\w-])(?:Candida)\\w*(?![\\w-])", "pages": ["21_3", "304_2"]}, "d:Наружное ухо": {"t": "Наружное ухо", "q": "Часть органа слуха, которая состоит из ушной раковины, наружного слухового прохода и кожного слоя барабанной перепонки.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 266", "re": "(?<![\\w-])(?:(?i:наружн\\w+\\s+ух\\w+))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "663_2"]}, "d:Наружный слуховой проход": {"t": "Наружный слуховой проход", "q": "Продолжение полости ушной раковины: начинается наружным слуховым отверстием и заканчивается барабанной перепонкой. Состоит из наружной перепончато-хрящевой и внутренней костной частей, длина которых соотносится как 2 : 1; форма определяется двумя изгибами, поэтому при осмотре ушную раковину оттягивают кзади и книзу.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 270", "re": "(?<![\\w-])(?:(?i:наружн\\w+\\s+слухов\\w+\\s+проход\\w*))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "314_3", "663_2", "812_1"]}, "d:Среднее ухо": {"t": "Среднее ухо", "q": "Система полостей и анатомических образований, обеспечивающая тимпанальное звукопроведение. К ней относятся барабанная перепонка, слуховые косточки с суставным, связочным и мышечным аппаратом и слуховая труба, а также соответствующие нервы и кровеносные сосуды.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 272", "re": "(?<![\\w-])(?:(?i:средн\\w+\\s+ух\\w+))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "314_3", "812_1"]}, "d:Головокружение": {"t": "Головокружение", "q": "Ощущение вращения: «внутреннее» (собственное вращение, ощущаемое при закрытых глазах) или «внешнее» (вращение окружающих предметов вокруг наблюдателя при открытых глазах). При раздражении вестибулярного аппарата направление головокружения совпадает с направлением вызванного нистагма.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 368", "re": "(?<![\\w-])(?:(?i:головокружени\\w+))\\w*(?![\\w-])", "pages": ["304_2", "812_1"]}, "d:Хондроперихондрит": {"t": "Хондроперихондрит", "q": "Воспаление надхрящницы, при котором в процесс вовлекается хрящ ушной раковины. Без адекватного лечения приводит к разрушению хряща и стойкой деформации раковины.", "book": "Probst R., Grevers G., Iro H. «Basic Otorhinolaryngology» (Thieme), с. 228–229 (PDF)", "re": "(?<![\\w-])(?:(?i:хондроперихондрит\\w*(?![\\w])(?!\\s+гортан)))\\w*(?![\\w-])", "pages": ["21_3", "304_2", "663_2"]}, "d:Синегнойная палочка": {"t": "Синегнойная палочка", "q": "Pseudomonas aeruginosa. Практически всегда является возбудителем злокачественного (некротизирующего) наружного отита; из-за широкого применения пероральных и местных фторхинолонов растёт доля штаммов, устойчивых к ципрофлоксацину. При остром мастоидите у детей по частоте выделения стоит на третьем месте после пневмококка и пиогенного стрептококка и особенно поражает детей с вентиляционными трубками и протекает с менее агрессивным течением.", "book": "Behrbohm H., Kaschke O., Nawka T., Swift A. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), PDF с. 166; Watkinson J. C., Clarke R. W. (eds). Scott-Brown’s Otorhinolaryngology, Head and Neck Surgery, 8th ed., vol. 2, p. 191 (PDF)", "re": "(?<![\\w-])(?i:с)инегнойн\\w+\\s+палочк\\w+|Pseudomonas aeruginosa\\w*(?![\\w-])", "pages": ["21_3", "304_2", "311_2", "663_2", "698_2", "812_1"]}}};
